'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare, compileRange, parse } = require('./src/semver');

// Literal, recursive, copy-on-choice reading of the contract (no early pruning).
function reference(registry, root) {
  const cat = name => Object.keys(registry[name] || {}).sort((a, b) => compare(b, a));
  function run(selected, cons, queue, cursor) {
    while (cursor < queue.length) {
      const name = queue[cursor++];
      if (selected.has(name)) continue;
      for (const v of cat(name).filter(v => (cons.get(name) || []).every(r => satisfies(v, r)))) {
        const s = new Map(selected); s.set(name, v);
        const c = new Map([...cons].map(([k, l]) => [k, [...l]]));
        const q = [...queue];
        let ok = true;
        for (const [d, r] of Object.entries(registry[name][v])) {
          if (!c.has(d)) c.set(d, []);
          c.get(d).push(r); q.push(d);
          if (s.has(d) && !satisfies(s.get(d), r)) { ok = false; break; }
        }
        if (!ok) continue;
        const out = run(s, c, q, cursor);
        if (out) return out;
      }
      return null;
    }
    return Object.fromEntries(selected);
  }
  const cons = new Map(), queue = [];
  for (const [d, r] of Object.entries(root)) { if (!cons.has(d)) cons.set(d, []); cons.get(d).push(r); queue.push(d); }
  return run(new Map(), cons, queue, 0);
}

// Directed checks.
assert.deepEqual(resolve({ w: { '1.9.0': {}, '1.10.0': {} } }, { w: '^1.0.0' }), { w: '1.10.0' });
assert.equal(satisfies('0.3.0', '^0.2.0'), false);
assert.equal(satisfies('0.2.9', '^0.2.0'), true);
