assert.equal(satisfies('1.3.0', '~1.2.3'), false);
assert.throws(() => compileRange('>= 1.0.0'), TypeError);
assert.throws(() => compileRange(' '), TypeError);
assert.throws(() => parse('01.0.0'), TypeError);
assert.deepEqual(resolve({}, {}), {});
assert.equal(resolve({}, { missing: '*' }), null);
assert.throws(() => resolve({ a: { '1.0.0': {} }, junk: { 'x': {} } }, { a: '*' }), TypeError);
assert.throws(() => resolve({ a: { '1.0.0': {} }, junk: { '1.0.0': { b: 'nope' } } }, { a: '*' }), TypeError);
// Stale constraint from an abandoned choice must be undone.
assert.deepEqual(resolve({
  a: { '2.0.0': { b: '^2.0.0', c: '^9.0.0' }, '1.0.0': { b: '^1.0.0' } },
  b: { '2.0.0': {}, '1.0.0': {} }, c: { '1.0.0': {} },
